-- User-authorized retirement of all WhatsApp records and public entrypoints, 2026-10-13.
-- Canonical recruitment records and schema are retained; no CASCADE is used.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
lock table public.whatsapp_contacts,public.whatsapp_campaigns,public.whatsapp_campaign_recipients,public.whatsapp_outbound_messages,public.whatsapp_inbound_messages,public.whatsapp_message_events,public.whatsapp_webhook_events in access exclusive mode;
do $$ begin
 if exists(select 1 from public.whatsapp_outbound_messages where state='sending') then raise exception 'In-flight sender requires reconciliation before removal'; end if;
end; $$;
revoke all on function public.accept_whatsapp_webhook_event(p_provider_event_key text, p_payload_sha256 text, p_event_category text, p_redacted_payload jsonb) from public,anon,authenticated,service_role;
revoke all on function public.admin_approve_selected_job_campaign(p_campaign_id uuid) from public,anon,authenticated,service_role;
revoke all on function public.admin_approve_sharing_campaign(p_campaign_id uuid) from public,anon,authenticated,service_role;
revoke all on function public.admin_approve_whatsapp_campaign(p_campaign_id uuid) from public,anon,authenticated,service_role;
revoke all on function public.admin_cancel_whatsapp_campaign(p_campaign_id uuid) from public,anon,authenticated,service_role;
revoke all on function public.admin_create_whatsapp_campaign(p_requirement_id uuid, p_operation_key uuid, p_campaign_name text, p_template_name text, p_template_language text, p_template_version text, p_criteria jsonb) from public,anon,authenticated,service_role;
revoke all on function public.admin_freeze_whatsapp_campaign_audience(p_campaign_id uuid, p_included_candidate_ids uuid[], p_excluded_candidate_ids uuid[], p_expected_included_count integer) from public,anon,authenticated,service_role;
revoke all on function public.admin_get_whatsapp_campaign(p_campaign_id uuid, p_limit integer, p_offset integer) from public,anon,authenticated,service_role;
revoke all on function public.admin_import_sharing_contacts(p_rows jsonb) from public,anon,authenticated,service_role;
revoke all on function public.admin_list_selected_job_campaigns() from public,anon,authenticated,service_role;
revoke all on function public.admin_list_sharing_campaigns() from public,anon,authenticated,service_role;
revoke all on function public.admin_list_sharing_contacts(p_requirement_id uuid, p_filters jsonb, p_offset integer) from public,anon,authenticated,service_role;
revoke all on function public.admin_list_whatsapp_campaigns(p_status text, p_limit integer, p_offset integer) from public,anon,authenticated,service_role;
revoke all on function public.admin_prepare_selected_job_campaign(p_requirement_id uuid, p_operation_key uuid, p_contact_ids uuid[], p_campaign_name text, p_template_name text, p_template_language text, p_template_version text) from public,anon,authenticated,service_role;
revoke all on function public.admin_prepare_sharing_campaign(p_requirement_id uuid, p_operation_key uuid, p_contact_ids uuid[], p_campaign_name text, p_template_name text, p_template_language text, p_template_version text) from public,anon,authenticated,service_role;
revoke all on function public.admin_preview_selected_job_contacts(p_requirement_id uuid, p_source text, p_view text, p_offset integer) from public,anon,authenticated,service_role;
revoke all on function public.admin_preview_whatsapp_campaign_audience(p_requirement_id uuid, p_criteria jsonb, p_limit integer, p_offset integer) from public,anon,authenticated,service_role;
revoke all on function public.admin_queue_selected_job_campaign(p_campaign_id uuid) from public,anon,authenticated,service_role;
revoke all on function public.admin_queue_sharing_campaign(p_campaign_id uuid) from public,anon,authenticated,service_role;
revoke all on function public.admin_queue_whatsapp_campaign(p_campaign_id uuid) from public,anon,authenticated,service_role;
revoke all on function public.admin_reconcile_whatsapp_campaign(p_campaign_id uuid) from public,anon,authenticated,service_role;
revoke all on function public.claim_whatsapp_outbound_batch(p_worker_id text, p_batch_size integer, p_lease_seconds integer) from public,anon,authenticated,service_role;
revoke all on function public.enqueue_whatsapp_outbound_message(p_contact_id uuid, p_candidate_id uuid, p_requirement_id uuid, p_purpose text, p_consent_class text, p_template_name text, p_template_language text, p_template_version text, p_template_variables jsonb, p_idempotency_key text, p_correlation_id uuid, p_max_attempts integer) from public,anon,authenticated,service_role;
revoke all on function public.get_candidate_whatsapp_alert_preference() from public,anon,authenticated,service_role;
revoke all on function public.get_whatsapp_contact_communication_status(p_contact_id uuid) from public,anon,authenticated,service_role;
revoke all on function public.get_whatsapp_core_health() from public,anon,authenticated,service_role;
revoke all on function public.list_whatsapp_failed_outbound(p_limit integer, p_offset integer) from public,anon,authenticated,service_role;
revoke all on function public.list_whatsapp_recent_inbound(p_limit integer, p_offset integer) from public,anon,authenticated,service_role;
revoke all on function public.list_whatsapp_recent_outbound(p_state text, p_limit integer, p_offset integer) from public,anon,authenticated,service_role;
revoke all on function public.mark_whatsapp_outbound_failure(p_message_id uuid, p_worker_id text, p_error_category text, p_error_code text, p_failure_kind text, p_retry_at timestamp with time zone) from public,anon,authenticated,service_role;
revoke all on function public.mark_whatsapp_outbound_sent(p_message_id uuid, p_worker_id text, p_provider_message_id text, p_provider_timestamp timestamp with time zone) from public,anon,authenticated,service_role;
revoke all on function public.mark_whatsapp_provider_call_started(p_message_id uuid, p_worker_id text) from public,anon,authenticated,service_role;
revoke all on function public.process_whatsapp_interested_response(p_inbound_message_id uuid) from public,anon,authenticated,service_role;
revoke all on function public.record_whatsapp_inbound_message(p_webhook_event_id uuid, p_contact_id uuid, p_provider_message_id text, p_provider_timestamp timestamp with time zone, p_message_type text, p_safe_text text, p_action_id text, p_correlation_key text, p_redacted_response jsonb) from public,anon,authenticated,service_role;
revoke all on function public.record_whatsapp_message_event(p_outbound_message_id uuid, p_webhook_event_id uuid, p_provider_event_key text, p_provider_message_id text, p_status text, p_provider_timestamp timestamp with time zone, p_payload_sha256 text, p_provider_error_category text, p_provider_error_code text) from public,anon,authenticated,service_role;
revoke all on function public.set_candidate_whatsapp_alert_preference(p_opt_in boolean, p_expected_updated_at timestamp with time zone, p_policy_version text, p_profile_token text) from public,anon,authenticated,service_role;
revoke all on function public.set_whatsapp_contact_suppression(p_contact_id uuid, p_suppressed boolean, p_source text, p_reason_category text) from public,anon,authenticated,service_role;
revoke all on function public.subscribe_whatsapp_sharing_updates(p_inbound_message_id uuid, p_preferences jsonb) from public,anon,authenticated,service_role;
revoke all on function public.upsert_whatsapp_inbound_contact(p_phone text) from public,anon,authenticated,service_role;
revoke all on table public.whatsapp_contacts,public.whatsapp_campaigns,public.whatsapp_campaign_recipients,public.whatsapp_outbound_messages,public.whatsapp_inbound_messages,public.whatsapp_message_events,public.whatsapp_webhook_events from public,anon,authenticated,service_role;
delete from public.whatsapp_message_events;
delete from public.whatsapp_inbound_messages;
delete from public.whatsapp_campaign_recipients;
delete from public.whatsapp_outbound_messages;
delete from public.whatsapp_campaigns;
delete from public.whatsapp_webhook_events;
delete from public.whatsapp_contacts;
delete from public.audit_logs where action like 'whatsapp.%' or entity_type like 'whatsapp_%';
commit;
